function typeOf(term, ctx) {
  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
  if (term[0] === 'var') return term[1] in ctx ? ctx[term[1]] : 'error';
  if (term[0] === 'lam') {
    const body = typeOf(term[3], Object.assign({}, ctx, { [term[1]]: term[2] }));
    return body === 'error' ? 'error' : ['->', term[2], body];
  }
  const f = typeOf(term[1], ctx), a = typeOf(term[2], ctx);
  if (f === 'error' || a === 'error') return 'error';
  return Array.isArray(f) && f[0] === '->' && same(f[1], a) ? f[2] : 'error';
}

