function distribute(p) {
  const a = p[0], s = p[1];
  return { tag: s.tag, v: [a, s.v] };
}

function isNormal(t) {
  if (t[0] === 'var') return true;
  if (t[0] === 'lam') return isNormal(t[2]);
  if (t[1][0] === 'lam') return false;
  return isNormal(t[1]) && isNormal(t[2]);
}

function composeTables(f, g) {
  return f.map(x => g[x]);
}

function isIso(f) {
  const n = f.length;
  const s = new Set(f);
  return s.size === n && f.every(x => Number.isInteger(x) && x >= 0 && x < n);
}

