function homSize(kind, a, b) {
  if (kind === 'product') return a * b;
  if (kind === 'coproduct') return a + b;
  if (kind === 'exponential') return Math.pow(b, a);
  if (kind === 'terminal') return 1;
  return 0;
}

function cardinality(t) {
  if (typeof t === 'number') return t;
  if (t === 'unit') return 1;
  if (t === 'void') return 0;
  const a = cardinality(t[1]), b = cardinality(t[2]);
  if (t[0] === 'x') return a * b;
  if (t[0] === '+') return a + b;
  return Math.pow(b, a);
}
